$ErrorActionPreference = "Stop"

function Normalize-LF([string]$text) { return $text.Replace("`r`n","`n").Replace("`r","`n") }
function Decode-B64([string]$b64) { return [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($b64)) }
function Replace-B64([string]$text,[string]$old64,[string]$new64,[string]$label) {
  $text = Normalize-LF $text
  $old = Normalize-LF (Decode-B64 $old64)
  $new = Normalize-LF (Decode-B64 $new64)
  $idx = $text.IndexOf($old)
  if ($idx -lt 0) { throw "Expected block not found: $label. Do not commit partial changes." }
  return $text.Substring(0,$idx) + $new + $text.Substring($idx + $old.Length)
}
function Write-Utf8NoBom([string]$path,[string]$text) {
  $enc = New-Object System.Text.UTF8Encoding($false)
  [System.IO.File]::WriteAllText($path,(Normalize-LF $text),$enc)
}

